471	export async function main() {
472	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
473	  const repo = process.env.CLAUDINITE_REPO || process.env.GITHUB_REPOSITORY;
474	  const base = process.env.CLAUDINITE_DEFAULT_BRANCH || 'main';
475	  const token = process.env.GITHUB_TOKEN;
476	  const requestFile = process.env.CLAUDINITE_REQUEST_AGENT;
477	  if (!repo) { console.error('baselining: no repo (CLAUDINITE_REPO/GITHUB_REPOSITORY)'); process.exit(1); }
478	  if (!token) { console.error('baselining: no GITHUB_TOKEN in env'); process.exit(1); }
479	
480	  const checksPath = join(root, '.claudinite-checks.json');
481	  if (!existsSync(checksPath)) { console.log('baselining: no .claudinite-checks.json — nothing to self-refresh'); return; }
482	  const priorRaw = JSON.parse(readFileSync(checksPath, 'utf8'));
483	  const priorStamp = priorRaw.claudinite ?? {};
484	  if (!priorStamp.updated && !priorStamp.ref) {
485	    console.log('baselining: no vendored-mount stamp — nothing to self-refresh (canon home or pre-adoption)');
486	    return; // quiet, no agent (matches the precondition self-skip)
487	  }
488	  const { delivery, materialize } = resolveDelivery(priorRaw?.maintenance?.delivery);
489	  if (!delivery) {
490	    console.error(`baselining: maintenance.delivery "${priorRaw?.maintenance?.delivery}" is neither auto-merge nor review`);
491	    process.exit(1);
492	  }
493	  // Materialize the missing key BEFORE the converge, so the repair rides this
494	  // cycle's maintenance commit like any other converged surface.
495	  if (materialize) {
496	    priorRaw.maintenance = { ...priorRaw.maintenance, delivery };
497	    writeFileSync(checksPath, JSON.stringify(priorRaw, null, 2) + '\n');
498	    console.log(`baselining: maintenance.delivery was missing — materialized "${delivery}"`);
499	  }
500	
501	  // 1. Fetch canon at head as a ROOTLESS tree (drop .git so apply-vendor-set's
502	  //    ancestry guards skip — a shallow clone can't answer them, and it is head
503	  //    by construction).
504	  const source = canonSource(process.env);
505	  const tmp = mkdtempSync(join(tmpdir(), 'claudinite-canon-'));
506	  git(source.ref
507	    ? ['clone', '--depth', '1', '--branch', source.ref, source.url, tmp]
508	    : ['clone', '--depth', '1', source.url, tmp]);
509	  const headSha = git(['-C', tmp, 'rev-parse', 'HEAD']).trim();
510	  rmSync(join(tmp, '.git'), { recursive: true, force: true });
511	  if (source.rehearsal) {
512	    console.log(`baselining: REHEARSAL against ${source.url}@${source.ref} (${headSha.slice(0, 8)}) — `
513	      + 'the stamp will be restored, and nothing is delivered');
514	  }
515	
516	  // 2-4. Deterministic converge: mount + stamp, then wiring, then mechanical notes.
517	  node([join(tmp, 'vendoring/apply-vendor-set.mjs'), '--target', root, '--ref', headSha]);
518	  const wiringOut = node([join(tmp, 'engine/scheduler/converge-wiring.mjs'), repo], { CLAUDINITE_REPO_ROOT: root });
519	  node([join(tmp, 'migrations/apply.mjs')], { CLAUDE_PROJECT_DIR: root });
520	
521	  // Ask about any declared secret the repo hasn't configured — but only once the
522	  // wiring is settled. On the cycle that FIRST stamps a name into the workflow the
523	  // value cannot be in this process's env yet, so asking then would nag about a
524	  // secret the owner may well have already added; next cycle tells the truth.
525	  const { declaredSecrets } = await import(pathToFileURL(join(tmp, 'engine/scheduler/converge-wiring.mjs')).href);
526	  const missingSecrets = wiringOut.includes('.github/workflows/claudinite-scheduler.yml')
527	    ? []
528	    : unconfiguredSecrets(await declaredSecrets(root, JSON.parse(readFileSync(checksPath, 'utf8'))), process.env);
529	  if (missingSecrets.length && await askForSecrets(token, repo, missingSecrets)) {
530	    console.log(`baselining: asked the owner to configure ${missingSecrets.join(', ')}`);
531	  }
532	
533	  // 5. Pending agentic notes (from the fresh canon clone) + stamp hold.
534	  const { loadMigrations, agenticMigrations } = await import(pathToFileURL(join(tmp, 'migrations/registry.mjs')).href);
535	  const pending = pendingAgentic(agenticMigrations(await loadMigrations()), priorStamp.updated);
536	  if (pending.length) {
537	    const raw = JSON.parse(readFileSync(checksPath, 'utf8'));
538	    raw.claudinite = { ...raw.claudinite, updated: heldStamp(pending) };
539	    writeFileSync(checksPath, JSON.stringify(raw, null, 2) + '\n');
540	  }
541	
542	  // 6. Meaningful change? A stamp-only bump against an unchanged head is not one —
543	  //    revert it and stay quiet (no nightly stamp-only noise).
544	  const changed = git(['-C', root, 'status', '--porcelain'])
545	    .split('\n').map((l) => l.slice(3)).filter(Boolean);
546	  // `materialize` excluded: a materialized delivery key also touches only
547	  // .claudinite-checks.json, and reverting it would re-drift the repo every night
548	  // and never land the repair.
549	  const onlyStamp = changed.length > 0 && !materialize && changed.every((p) => p === '.claudinite-checks.json');
550	  if (onlyStamp && priorStamp.ref === headSha && !pending.length) {
551	    git(['-C', root, 'checkout', '--', '.claudinite-checks.json']);
552	    console.log('baselining: mount already at canon head, nothing changed — agentless, quiet');
553	    return;
554	  }
555	  const meaningfulChange = changed.length > 0;
556	
557	  // 6b. SELF-TEST the converged tree before judging its content. This asks "can
558	  //     Claudinite still run here?" — mount, stamp, pack manifests, hook targets,
559	  //     mounted skills, cron, migrations registry — and it is the gate that would
560	  //     have caught #555 the night it landed: a required manifest field arrived
561	  //     with no migration, every consumer pack stopped validating, and because a
562	  //     pack that fails validation contributes NO rules, check_the_world went on
563	  //     reporting green about a corpus it was no longer running. A content check
564	  //     cannot see its own machinery break. This runs on the just-converged tree,
565	  //     so it judges what the member is about to live with.
566	  const selftestOk = selfTestPasses(root);
567	  if (!selftestOk) console.log('baselining: the converged mount FAILED its self-test — requesting the agent');
568	
569	  // 7. Escalation gate: run the conformance checks only when a change happened and
570	  //    no agentic note already forces the agent. A failed self-test forces it too:
571	  //    broken machinery is exactly the judgment case, and merging it would spread
572	  //    the breakage to a repo that was working an hour ago.
573	  const checksPass = (meaningfulChange && !pending.length) ? checkTheWorldPasses(root) : true;
574	  const requestAgent = shouldRequestAgent({ pendingCount: pending.length, meaningfulChange, checksPass, selftestOk });
575	
576	  // 7b. A REHEARSAL stops here. It has done the only thing it was for — converged
577	  //     this real repo against a canon BRANCH and asked whether the result still
578	  //     works — and now it must leave no trace: no commit, no branch, no PR, and
579	  //     above all no stamp. Stamping a branch head would leave the member
580	  //     `ref-not-on-trunk`, which the #328 anti-rewind guard then refuses to
581	  //     converge over: a rehearsal that wedged the repo it was rehearsing on.
582	  //     `git checkout -- .` restores the working tree wholesale, so the mount goes
583	  //     back to the vendored snapshot the repo actually runs.
584	  if (source.rehearsal) {
585	    git(['-C', root, 'checkout', '--', '.']);
586	    const verdict = selftestOk && checksPass ? 'PASS' : 'FAIL';
587	    console.log(`baselining: rehearsal ${verdict} — selftest ${selftestOk ? 'ok' : 'FAILED'}, `
588	      + `checks ${checksPass ? 'green' : 'RED'}, ${changed.length} file(s) would have changed. Working tree restored.`);
589	    if (verdict === 'FAIL') process.exit(1);   // the canary's whole purpose: fail the canon PR
590	    return;
591	  }
592	
593	  // 8. Deliver the converge (only when there's something to land).
594	  if (meaningfulChange || pending.length) {
595	    const seed = Math.random().toString(36).slice(2, 8);
596	    const branch = await deliver(root, repo, base, token, delivery, seed);
597	    console.log(`baselining: delivered converge on ${branch} (${delivery})`);
598	  } else {
599	    console.log('baselining: no change to deliver');
600	  }
601	
602	  // 9. Request the agent only when judgment is left (conditional handoff, §3).
603	  if (requestAgent && requestFile) writeFileSync(requestFile, `${AGENT_REQUEST_MARKER}\n`);
604	  console.log(requestAgent
605	    ? `baselining: requested agent stage (${pending.length ? `${pending.length} agentic note(s)` : 'conformance not green'})`
606	    : 'baselining: agentless night — deterministic converge delivered, no agent needed');
607	}
608	
609	// Run only when invoked directly (the scheduler's `node worker.mjs`), never on
610	// import — a test imports the pure helpers without any git or network.
611	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
612	  main().catch((e) => { console.error(`baselining preprocessing failed: ${e.message}`); process.exit(1); });
613	}
